% mathsmap-diagram-colours {"version":1,"kind":"geometry","base":[],"semantic":[],"reference":"source page 21 question 7b authored sample solution"}
\begin{tikzpicture}[every node/.style={font=\fontsize{10}{12}\selectfont}]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\coordinate (O) at (0,0);\pgfmathsetmacro{\lo}{atan2(0.13,2.45)}\pgfmathsetmacro{\hi}{atan2(2.25,-1)}
\coordinate (A) at (\hi:3);\coordinate (B) at (\lo:3);
\draw[black,line width=0.8pt] (A)--(O)--(B);
\foreach \k in {1,...,7}{\pgfmathsetmacro{\ang}{\lo+\k*(\hi-\lo)/8}\draw[black,line width=0.8pt] (O)--(\ang:3);}
\foreach \k in {0,...,7}{\pgfmathsetmacro{\st}{\lo+\k*(\hi-\lo)/8}\pgfmathsetmacro{\en}{\lo+(\k+1)*(\hi-\lo)/8}\draw[black,line width=0.4pt] (\st:0.8) arc[start angle=\st,end angle=\en,radius=0.8];\pgfmathsetmacro{\mid}{(\st+\en)/2}\draw[black,line width=0.4pt] (\mid:0.75)--(\mid:0.85);}
\node[above left] at (A) {$A$};\node[right] at (B) {$B$};\node[below left] at (O) {$O$};
\end{tikzpicture}
